/**
 * @summary Full-text search across quotations and items by part number or supplier
 */
export const getSearchQuotationsUrl = (params: SearchQuotationsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/search?${stringifiedParams}`
    : `/api/search`;
};

export const searchQuotations = async (
  params: SearchQuotationsParams,
  options?: RequestInit,
): Promise<SearchResults> => {
  return customFetch<SearchResults>(getSearchQuotationsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getSearchQuotationsQueryKey = (
  params?: SearchQuotationsParams,
) => {
  return [`/api/search`, ...(params ? [params] : [])] as const;
};

export const getSearchQuotationsQueryOptions = <
  TData = Awaited<ReturnType<typeof searchQuotations>>,
  TError = ErrorType<unknown>,
>(
  params: SearchQuotationsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof searchQuotations>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getSearchQuotationsQueryKey(params);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof searchQuotations>>
  > = ({ signal }) => searchQuotations(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof searchQuotations>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type SearchQuotationsQueryResult = NonNullable<
  Awaited<ReturnType<typeof searchQuotations>>
>;
export type SearchQuotationsQueryError = ErrorType<unknown>;

